(()=>{'use strict';
let mode='home',frame=null;const native=window.MooncatchNative,oldBack=window.MooncatchBack,oldLife=window.MooncatchLifecycle;
const style=document.createElement('style');style.textContent=`#suiteHome{position:fixed;inset:0;z-index:2500;overflow:auto;background:radial-gradient(ellipse at 20% 0%,#244550,#0b1728 70%);color:#e5f0ed;padding:max(28px,var(--native-safe-top,env(safe-area-inset-top))) max(20px,var(--native-safe-right,env(safe-area-inset-right))) max(24px,var(--native-safe-bottom,env(safe-area-inset-bottom))) max(20px,var(--native-safe-left,env(safe-area-inset-left)));display:grid;place-content:center;gap:18px;font-family:system-ui}#suiteHome[hidden],#echoFrame[hidden]{display:none}#suiteHome h1{font-size:32px;margin:0}#suiteHome p{max-width:600px;line-height:1.6;color:#b5cbcf}#suiteCards{display:flex;gap:16px;flex-wrap:wrap}#suiteCards button{flex:1;min-width:230px;max-width:390px;text-align:left;padding:26px;border:1px solid #668582;background:#17303e;border-radius:20px;color:#e1eee9;font:inherit;cursor:pointer;min-height:160px}#suiteCards strong{display:block;font-size:24px;margin:8px 0}#suiteCards small{line-height:1.7;display:block;color:#b4c9cc}#suiteCards button:active{background:#28505c}#suiteReturn{min-height:44px;margin:8px}#echoFrame{position:fixed;inset:0;width:100%;height:100%;border:0;z-index:2400;background:#091421}`;document.head.append(style);
const home=document.createElement('section');home.id='suiteHome';home.innerHTML='<div class="suite-intro"><small class="suite-kicker">MOONCATCH · 月港出发厅</small><h1>月面拾光</h1><p>一艘月舟，一道同行的影子。<br>选择今天的旅程，让星光带你出发。</p></div><div id="suiteCards"><button id="chooseClassic"><span class="suite-symbol" aria-hidden="true">✦</span><span><strong>星海航行</strong><small>驾驶月舟，穿越星海与遗迹<br>限时挑战 / 无尽巡航 / 自由漫游</small></span><span class="suite-arrow" aria-hidden="true">↗</span></button><button id="chooseEcho"><span class="suite-symbol" aria-hidden="true">☾</span><span><strong>月影同行</strong><small>与另一个自己，解开月面机关<br>30 关 · 对称 / 接力 / 回响 / 月纹</small></span><span class="suite-arrow" aria-hidden="true">→</span></button></div><div class="suite-footer"><span>月港通讯正常 · 随时可以返航</span><span>离线可玩 · 进度自动保存</span></div>';document.body.append(home);
function child(){return frame?.contentWindow?.MoonEcho}
function insets(){if(!frame?.contentDocument)return;for(const s of ['top','right','bottom','left'])frame.contentDocument.documentElement.style.setProperty('--safe-'+s,getComputedStyle(document.documentElement).getPropertyValue('--native-safe-'+s)||'0px');child()?.draw()}
function freeze(){if(typeof clearInput==='function')clearInput();if(typeof stopMusic==='function')stopMusic();if(typeof state!=='undefined'&&['playing','resuming','menuIntro'].includes(state)&&typeof pause==='function')pause();}
function select(value){freeze();mode=value;home.hidden=value!=='home';if(frame)frame.hidden=value!=='echo';if(value==='echo'){if(!frame){frame=document.createElement('iframe');frame.id='echoFrame';frame.title='月影同行解谜棋盘';frame.src='echo/index.html?v=29';frame.onload=()=>{insets();child()?.pause(mode!=='echo');frame.contentWindow.focus()};document.body.append(frame)}child()?.pause(false);frame.contentWindow.focus()}else child()?.pause(true);native?.files.setAwake({awake:value==='echo'}).catch(()=>{});}
window.MooncatchSuite={get mode(){return mode},select,home:()=>select('home')};
function press(el,fn){let down=null;el.addEventListener('pointerdown',e=>{if(e.button!==0)return;down={id:e.pointerId,x:e.clientX,y:e.clientY};el.setPointerCapture?.(e.pointerId)});el.addEventListener('pointerup',e=>{const d=down;down=null;if(d&&d.id===e.pointerId&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<14){e.preventDefault();fn()}});el.addEventListener('pointercancel',()=>down=null);el.addEventListener('lostpointercapture',()=>down=null);el.addEventListener('click',e=>{if(e.detail===0)fn()})}press(document.getElementById('chooseClassic'),()=>select('classic'));press(document.getElementById('chooseEcho'),()=>select('echo'));
const back=document.createElement('button');back.id='suiteReturn';back.textContent='切换玩法';back.onclick=()=>select('home');(document.querySelector('#nativeHome header')||document.querySelector('main')).append(back);
const settingsBack=document.createElement('button');settingsBack.id='suiteSettingsReturn';settingsBack.textContent='暂停航行并切换玩法';settingsBack.onclick=()=>select('home');document.getElementById('controlSettings')?.append(settingsBack);
window.MooncatchBack=()=>{if(window.MoonGuide?.active){window.MoonGuide.close();return}if(mode==='echo'){child()?.back();return}if(mode==='home'){window.MooncatchSaveChanged?.().then(()=>native?.App.exitApp());return}if(native&&window.MooncatchIsHome?.()){select('home');return}oldBack?.()};
window.MooncatchLifecycle=active=>{if(mode==='classic')oldLife?.(active);else{freeze();child()?.pause(!active);native?.files.setAwake({awake:active&&mode==='echo'}).catch(()=>{});if(!active)window.MooncatchSaveChanged?.()}};
addEventListener('mooncatchInsets',()=>requestAnimationFrame(insets));addEventListener('resize',insets);select('home');document.documentElement.removeAttribute('data-suite-loading');document.getElementById('suiteLoading')?.remove();
})();
